//
// Każdy glif: 16 wierszy po 8 pikseli, bit 7 = lewy piksel.
// Tablica posortowana po znaku (wyszukiwanie binarne).

pub const WIDTH: usize = 8;
pub const HEIGHT: usize = 16;

pub fn glyph(c: char) -> &'static [u8; HEIGHT] {
    match GLYPHS.binary_search_by(|(g, _)| g.cmp(&c)) {
        Ok(i) => &GLYPHS[i].1,
        Err(_) => match GLYPHS.binary_search_by(|(g, _)| g.cmp(&'?')) {
            Ok(i) => &GLYPHS[i].1,
            Err(_) => &GLYPHS[0].1,
        },
    }
}

